def gen(rng):
    def fmt(text, word, rep):
        return text + '\n' + word + '\n' + rep
    def para(n, alpha, sp):
        s = []
        for i in range(n):
            if 0 < i < n - 1 and s[-1] != ' ' and rng.random() < sp:
                s.append(' ')
            else:
                s.append(rng.choice(alpha))
        return ''.join(s)
    tests = [
        fmt('the cat sat on the mat with a cat', 'cat', 'dog'),
        fmt('aaaaa', 'aa', 'X'),
        fmt('banana bandana', 'ana', '#'),
        fmt('hello', 'hello', '*****'),
        fmt('hello', 'world', '#'),
        fmt('a', 'a', 'b'),
        fmt('abc abc abc', 'abc', 'abc'),
        fmt('aaaa aaaa', 'aaa', 'zz'),
        fmt('ababababab', 'abab', '1'),
    ]
    for n in (5, 10, 20, 40, 80, 150, 300):
        for _ in range(3):
            alpha = rng.choice(['ab', 'abc', 'abcdefgh'])
            text = para(n, alpha, rng.choice([0.0, 0.15]))
            m = rng.randint(1, min(5, n))
            if rng.random() < 0.7:
                st = rng.randrange(n - m + 1)
                word = text[st:st + m].replace(' ', '') or rng.choice(alpha)
            else:
                word = ''.join(rng.choice(alpha) for _ in range(m))
            rep = ''.join(rng.choice('xyz*#@19') for _ in range(rng.randint(1, 5)))
            tests.append(fmt(text, word, rep))
    N = 300000
    tests.append(fmt('a' * N, 'a' * 99999 + 'b', 'X'))
    tests.append(fmt('a' * N, 'a' * 1000, 'ZZ'))
    tests.append(fmt(para(N, 'ab', 0.05), 'abababababababababab', '#'))
    tests.append(fmt(para(N, 'abcdefghijklmnopqrstuvwxyz', 0.15), 'e', '*'))
    return tests
